package popcount

import "math/bits"

var _ = bits.OnesCount64

// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	const (
		m1 = 0x5555555555555555
		m2 = 0x3333333333333333
		m4 = 0x0f0f0f0f0f0f0f0f
		m8 = 0x00ff00ff00ff00ff
		h1 = 0x0101010101010101
		h2 = 0x0001000100010001
	)
	n := 0
	for len(xs) >= 8 {
		a, b, c, d := xs[0], xs[1], xs[2], xs[3]
		e, f, g, h := xs[4], xs[5], xs[6], xs[7]
		// 2-bit fields
		a -= a >> 1 & m1
		b -= b >> 1 & m1
		c -= c >> 1 & m1
		d -= d >> 1 & m1
		e -= e >> 1 & m1
		f -= f >> 1 & m1
		g -= g >> 1 & m1
		h -= h >> 1 & m1
		// 4-bit fields (<=4), pair-add to <=8
		p0 := a&m2 + a>>2&m2 + b&m2 + b>>2&m2
		p1 := c&m2 + c>>2&m2 + d&m2 + d>>2&m2
		p2 := e&m2 + e>>2&m2 + f&m2 + f>>2&m2
		p3 := g&m2 + g>>2&m2 + h&m2 + h>>2&m2
		// bytes (<=16 each), then sum (<=64)
		s := (p0 + p0>>4) & m4
		s += (p1 + p1>>4) & m4
		s += (p2 + p2>>4) & m4
		s += (p3 + p3>>4) & m4
		// 16-bit fields (<=128), horizontal sum via multiply
		t := s&m8 + s>>8&m8
		n += int(t * h2 >> 48)
		xs = xs[8:]
	}
	for _, x := range xs {
		x -= x >> 1 & m1
		x = x&m2 + x>>2&m2
		x = (x + x>>4) & m4
		n += int(x * h1 >> 56)
	}
	return n
}

